log=(R/'Diva.log').read_text();assert'ERROR 'not in log;notes=[s for s in log.splitlines()if s.startswith('NOTE ')];assert len(notes)==12 and notes==[s for s in(base/'Diva.log').read_text().splitlines()if s.startswith('NOTE ')]
