proof=dict(UTC=datetime.datetime.now(datetime.timezone.utc).isoformat(),actual_Diva_executed=True,original_source_preset_SHA256=hashlib.sha256(Path(seed['source_preset']).read_bytes()).hexdigest(),all281_parameters_exact=True,all12_MIDI_events_exact=True,only_three_held_notes_each_phrase=True,source_audio_arrays_exact=True,source_audio_max_abs_error=float(abs(old-new).max()),root=str(R),reference_not_used_as_synth_input=True,reference_match_reached=False);(V/'ACTUAL_DIVA_SOURCE_RECHECK.json').write_text(json.dumps(proof,indent=2)+'\n');(R/'PROOF.json').write_text(json.dumps(proof,indent=2)+'\n');print(json.dumps(proof),flush=True)
